CREATE TABLE t (a INT, b TEXT);
INSERT INTO t VALUES (1, 'a'), (3, 'c'), (5, 'e'), (7, 'g'), (9, 'i'), (5, 'e2');
CREATE INDEX idx_a ON t (a);
SELECT * FROM t WHERE a > 5;
SELECT * FROM t WHERE a >= 5;
SELECT * FROM t WHERE a < 5;
